dataset = [
    ("science fiction", "france"),
    ("fiction", "hong kong"),
    ("science fiction", "france"),
    ("humanities", "uk"),
    ("science fiction", "spain"),
    ("fiction", "chile"),
]

def most_frequent_countries(data):
    countries = {}
    for category, country in data:
        if country not in countries:
            countries[country] = 0
        countries[country] += 1
    return max(countries, key=countries.get)

most_frequent_countries(dataset)

face_id = requests.get('http://127.0.0.1:5000/user/1/faces')
if face_id.status_code == 200:
    face_id_json = face_id.json()
    recognized_faces = []
    for face in face_id_json['faces']:
        results = requests.get(f'https://api.faceid.com/identify/{face}')
        if results.status_code == 200:
            recognized_faces.append(results.json())
else:
    print("Failed to get user's face info")
